import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import Navbar from '../components/Navbar';
import { FaBrain, FaExclamationTriangle, FaChartLine, FaCalendarAlt, FaClock, FaBook, FaUniversity, FaHeartbeat, FaMoon, FaCoffee, FaSmile, FaFrown, FaMeh } from 'react-icons/fa';

function Burnout() {
  const navigate = useNavigate();
  const [assessment, setAssessment] = useState({
    exhaustion: '',
    cynicism: '',
    efficiency: '',
    sleepQuality: '',
    stressLevel: '',
    motivation: ''
  });
  const [result, setResult] = useState(null);
  const [showResult, setShowResult] = useState(false);

  const handleChange = (field, value) => {
    setAssessment({ ...assessment, [field]: value });
  };

  const calculateBurnout = () => {
    let score = 0;
    if (assessment.exhaustion === 'high') score += 3;
    if (assessment.exhaustion === 'medium') score += 2;
    if (assessment.exhaustion === 'low') score += 1;
    
    if (assessment.cynicism === 'high') score += 3;
    if (assessment.cynicism === 'medium') score += 2;
    if (assessment.cynicism === 'low') score += 1;
    
    if (assessment.efficiency === 'low') score += 3;
    if (assessment.efficiency === 'medium') score += 2;
    if (assessment.efficiency === 'high') score += 1;
    
    if (assessment.stressLevel === 'high') score += 3;
    if (assessment.stressLevel === 'medium') score += 2;
    if (assessment.stressLevel === 'low') score += 1;
    
    let level = '';
    let advice = '';
    let color = '';
    
    if (score <= 6) {
      level = 'Low Risk';
      advice = 'You\'re doing well! Keep maintaining healthy habits and take regular breaks.';
      color = '#2ecc71';
    } else if (score <= 10) {
      level = 'Moderate Risk';
      advice = 'You\'re showing early signs of burnout. Take time to recharge and set boundaries.';
      color = '#f39c12';
    } else {
      level = 'High Risk';
      advice = 'You may be experiencing burnout. Consider talking to a counselor, taking a break, and prioritizing self-care.';
      color = '#e74c3c';
    }
    
    setResult({ score, level, advice, color });
    setShowResult(true);
  };

  const options = [
    { value: 'low', label: 'Low', color: '#2ecc71' },
    { value: 'medium', label: 'Medium', color: '#f39c12' },
    { value: 'high', label: 'High', color: '#e74c3c' }
  ];

  return (
    <div style={styles.container}>
      <Navbar />
      <div style={styles.content}>
        <div style={styles.header}>
          <h1 style={styles.title}>🔥 Academic Burnout Check</h1>
          <p style={styles.subtitle}>Assess your risk of academic burnout</p>
        </div>

        <div style={styles.card}>
          <div style={styles.questionSection}>
            <h3><FaBrain /> How often do you feel emotionally exhausted after studying?</h3>
            <div style={styles.options}>
              {options.map(opt => (
                <button
                  key={opt.value}
                  onClick={() => handleChange('exhaustion', opt.value)}
                  style={{...styles.optionBtn, background: assessment.exhaustion === opt.value ? opt.color : '#f0f0f0', color: assessment.exhaustion === opt.value ? 'white' : '#333'}}
                >
                  {opt.label}
                </button>
              ))}
            </div>
          </div>

          <div style={styles.questionSection}>
            <h3><FaExclamationTriangle /> Do you feel cynical or detached from your studies?</h3>
            <div style={styles.options}>
              {options.map(opt => (
                <button
                  key={opt.value}
                  onClick={() => handleChange('cynicism', opt.value)}
                  style={{...styles.optionBtn, background: assessment.cynicism === opt.value ? opt.color : '#f0f0f0', color: assessment.cynicism === opt.value ? 'white' : '#333'}}
                >
                  {opt.label}
                </button>
              ))}
            </div>
          </div>

          <div style={styles.questionSection}>
            <h3><FaChartLine /> How would you rate your academic efficiency?</h3>
            <div style={styles.options}>
              {options.map(opt => (
                <button
                  key={opt.value}
                  onClick={() => handleChange('efficiency', opt.value)}
                  style={{...styles.optionBtn, background: assessment.efficiency === opt.value ? opt.color : '#f0f0f0', color: assessment.efficiency === opt.value ? 'white' : '#333'}}
                >
                  {opt.label === 'low' ? 'Low' : opt.label === 'medium' ? 'Medium' : 'High'}
                </button>
              ))}
            </div>
          </div>

          <div style={styles.questionSection}>
            <h3><FaHeartbeat /> What is your current stress level?</h3>
            <div style={styles.options}>
              {options.map(opt => (
                <button
                  key={opt.value}
                  onClick={() => handleChange('stressLevel', opt.value)}
                  style={{...styles.optionBtn, background: assessment.stressLevel === opt.value ? opt.color : '#f0f0f0', color: assessment.stressLevel === opt.value ? 'white' : '#333'}}
                >
                  {opt.label}
                </button>
              ))}
            </div>
          </div>

          <button onClick={calculateBurnout} style={styles.assessBtn}>
            Assess My Burnout Risk
          </button>

          {showResult && result && (
            <div style={{...styles.resultCard, borderTop: `4px solid ${result.color}`}}>
              <h3>Your Burnout Assessment Result</h3>
              <div style={styles.resultScore}>
                <span style={{fontSize: '48px', fontWeight: 'bold', color: result.color}}>{result.score}</span>
                <span>/15</span>
              </div>
              <div style={{...styles.resultLevel, background: `${result.color}20`, color: result.color}}>
                {result.level}
              </div>
              <p style={styles.resultAdvice}>{result.advice}</p>
              {result.level === 'High Risk' && (
                <div style={styles.emergencyTip}>
                  <FaHeartbeat /> Consider reaching out to a counselor or trusted person for support.
                </div>
              )}
            </div>
          )}
        </div>

        <div style={styles.tipsCard}>
          <h3>💡 Burnout Prevention Tips</h3>
          <ul>
            <li>Take regular breaks between study sessions</li>
            <li>Maintain a consistent sleep schedule</li>
            <li>Set realistic goals and boundaries</li>
            <li>Connect with friends and peers</li>
            <li>Practice mindfulness and deep breathing</li>
          </ul>
        </div>
      </div>
    </div>
  );
}

const styles = {
  container: { minHeight: '100vh', background: 'linear-gradient(135deg, #667eea 0%, #764ba2 100%)' },
  content: { maxWidth: '700px', margin: '0 auto', padding: '20px', paddingTop: '80px' },
  header: { textAlign: 'center', marginBottom: '30px', color: 'white' },
  title: { fontSize: '32px', marginBottom: '10px' },
  subtitle: { fontSize: '14px', opacity: 0.9 },
  card: { background: 'white', borderRadius: '20px', padding: '25px', marginBottom: '20px' },
  questionSection: { marginBottom: '25px', paddingBottom: '15px', borderBottom: '1px solid #eee' },
  options: { display: 'flex', gap: '10px', marginTop: '10px' },
  optionBtn: { padding: '8px 20px', borderRadius: '25px', border: 'none', cursor: 'pointer', fontWeight: '500' },
  assessBtn: { width: '100%', padding: '14px', background: 'linear-gradient(135deg, #667eea 0%, #764ba2 100%)', color: 'white', border: 'none', borderRadius: '12px', fontSize: '16px', fontWeight: 'bold', cursor: 'pointer', marginTop: '15px' },
  resultCard: { marginTop: '20px', padding: '20px', background: '#f8f9ff', borderRadius: '15px', textAlign: 'center' },
  resultScore: { margin: '15px 0' },
  resultLevel: { display: 'inline-block', padding: '5px 15px', borderRadius: '20px', fontSize: '14px', fontWeight: 'bold' },
  resultAdvice: { marginTop: '15px', color: '#555', lineHeight: 1.5 },
  emergencyTip: { marginTop: '15px', padding: '10px', background: '#ffeaa7', borderRadius: '10px', fontSize: '13px' },
  tipsCard: { background: 'white', borderRadius: '20px', padding: '20px' },
};

export default Burnout;
